function createEventJournal(options = {}) {
  if (!options || typeof options !== 'object' || Array.isArray(options)) throw new TypeError('options must be an object');
  const { minimum = 'info', mode = 'development' } = options;
  const ranks = { debug: 10, info: 20, warn: 30, error: 40 };
  if (!Object.prototype.hasOwnProperty.call(ranks, minimum)) throw new TypeError('invalid minimum');
  if (typeof mode !== 'string' || mode.trim() === '') throw new TypeError('mode must be a non-empty string');
  const fileLines = [];
  const consoleLines = [];
  let sequence = 0;

  const copyContext = context => {
    if (!context || typeof context !== 'object' || Array.isArray(context)) throw new TypeError('context must be an object');
    let encoded;
    try {
      encoded = JSON.stringify(context);
    } catch (error) {
      throw new TypeError('context must be JSON-compatible');
    }
    if (encoded === undefined) throw new TypeError('context must be JSON-compatible');
    return JSON.parse(encoded);
  };

  function write(level, message, context = {}) {
    if (!Object.prototype.hasOwnProperty.call(ranks, level)) throw new TypeError('invalid level');
    if (typeof message !== 'string') throw new TypeError('message must be a string');
    if (ranks[level] <= ranks[minimum]) return false;
    const safeContext = copyContext(context);
    sequence += 1;
    fileLines.push(JSON.stringify({ sequence, level, message, context: safeContext }));
    if (mode !== 'production' && mode !== 'test') consoleLines.push(level.toUpperCase() + ': ' + message);
    return true;
  }

  function snapshot() {
    return { fileLines: fileLines.slice(), consoleLines: consoleLines.slice() };
  }

  return { write, snapshot };
}

module.exports = { createEventJournal };

