'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createEventJournal']);
const { createEventJournal } = api;

const journal = createEventJournal({ minimum: 'info', mode: 'development' });
assert.deepStrictEqual(journal.snapshot(), { fileLines: [], consoleLines: [] });
assert.strictEqual(journal.write('debug', 'ignored', { ignored: true }), false);
const context = { request: { id: 7 }, tags: ['a'] };
assert.strictEqual(journal.write('info', '', context), true);
context.request.id = 99;
context.tags.push('changed');
assert.strictEqual(journal.write('error', 'failed', { retry: false }), true);
const snapshot = journal.snapshot();
assert.deepStrictEqual(snapshot.consoleLines, ['INFO: ', 'ERROR: failed']);
assert.strictEqual(snapshot.fileLines.length, 2);
assert.strictEqual(snapshot.fileLines[0], '{"sequence":1,"level":"info","message":"","context":{"request":{"id":7},"tags":["a"]}}');
assert.strictEqual(snapshot.fileLines[1], '{"sequence":2,"level":"error","message":"failed","context":{"retry":false}}');
assert.deepStrictEqual(Object.keys(JSON.parse(snapshot.fileLines[0])), ['sequence', 'level', 'message', 'context']);
snapshot.fileLines.push('leak');
snapshot.consoleLines[0] = 'changed';
assert.strictEqual(journal.snapshot().fileLines.length, 2);
assert.deepStrictEqual(journal.snapshot().consoleLines, ['INFO: ', 'ERROR: failed']);

for (const mode of ['production', 'test']) {
  const quiet = createEventJournal({ minimum: 'debug', mode });
  assert.strictEqual(quiet.write('debug', 'visible in file', {}), true);
  assert.deepStrictEqual(quiet.snapshot().consoleLines, []);
}
const alternate = createEventJournal({ mode: 'staging' });
alternate.write('warn', 'careful', {});
assert.deepStrictEqual(alternate.snapshot().consoleLines, ['WARN: careful']);

for (const options of [null, { minimum: 'trace' }, { minimum: 1 }, { mode: '' }, { mode: 2 }]) {
  assert.throws(() => createEventJournal(options));
}
for (const action of [
  () => journal.write('trace', 'x', {}),
  () => journal.write('warn', 123, {}),
  () => journal.write('warn', 'x', null),
  () => journal.write('warn', 'x', []),
  () => journal.write('warn', 'x', { big: 1n })
]) assert.throws(action);
const cyclic = {};
cyclic.self = cyclic;
assert.throws(() => journal.write('warn', 'cyclic', cyclic));
assert.strictEqual(journal.write('warn', 'after failures', {}), true);
assert.strictEqual(JSON.parse(journal.snapshot().fileLines[2]).sequence, 3);

